// === Tab: mySketch ===
/**
 * SILICO_MYCELIUM // DIGITAL_SYMBIOSIS
 * Trend: Bio-Computing & Artificial Life.
 * * CONCEPT:
 * Simulating the intelligence of fungal networks (Mycelium).
 * It explores, branches, and connects based on nutrient availability.
 * * CONTROLS:
 * - MOUSE MOVE: Release nutrients (Attracts growth).
 * - CLICK: Plant new spores (New colonies).
 */

let hyphae = []; // Les filaments
let nutrients = []; // La nourriture
let colors;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0);
  noSmooth();

  // Palette Bioluminescente
  colors = [
    color(20, 255, 200, 50), // Cyan Spore
    color(200, 100, 255, 50), // Purple Enzyme
    color(255, 255, 200, 80)  // White Core
  ];

  // Démarrage avec une colonie centrale
  for(let i=0; i<10; i++){
    hyphae.push(new Hypha(createVector(width/2, height/2), random(TWO_PI)));
  }
}

function draw() {
  // Pas de background() complet pour laisser la structure se construire (Peinture cumulative)
  // Juste un fade ultra-lent pour la profondeur
  noStroke();
  fill(0, 5); 
  rect(0, 0, width, height);

  // 1. GESTION DES NUTRIMENTS (SOURIS)
  // La souris dépose de la nourriture invisible qui attire les branches
  if (frameCount % 5 === 0) {
    nutrients.push(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-50, 50), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-50, 50)));
  }

  // Limite le nombre de nutriments pour la perf
  if (nutrients.length > 200) nutrients.shift();

  // 2. CROISSANCE DU MYCELIUM
  blendMode(ADD); // Effet lumière

  for (let i = hyphae.length - 1; i >= 0; i--) {
    let h = hyphae[i];
    h.update();
    h.display();

    // Si le filament est "fatigué" ou sort de l'écran, il meurt
    if (h.life <= 0 || h.isDead) {
      hyphae.splice(i, 1);
    } else {
      // PROBABILITÉ DE BRANCHEMENT (Reproduction)
      // Plus il y a de nutriments proches, plus ça branche
      if (random() < 0.02 && hyphae.length < 2000) {
        hyphae.push(h.branch());
      }
    }
  }

  blendMode(BLEND);
  drawUI();
}

class Hypha {
  constructor(pos, angle) {
    this.pos = pos.copy();
    this.prevPos = pos.copy();
    this.vel = p5.Vector.fromAngle(angle);
    this.life = 200; // Durée de vie
    this.isDead = false;
    this.color = random(colors);
    this.wobble = random(0.05, 0.2); // Capacité à zigzaguer
  }

  update() {
    this.life--;
    this.prevPos = this.pos.copy();

    // 1. SENSING (L'IA du champignon)
    // Chercher le nutriment le plus proche
    let closest = null;
    let recordDist = 150; // Rayon de perception

    for (let n of nutrients) {
      let d = this.pos.dist(n);
      if (d < recordDist) {
        recordDist = d;
        closest = n;
      }
    }

    // 2. DECISION MAKING
    if (closest) {
      // Si on a trouvé à manger, on tourne vers la cible
      let desired = p5.Vector.sub(closest, this.pos);
      desired.setMag(1); // Vitesse constante
      // Steering behavior (mouvement fluide)
      this.vel.lerp(desired, 0.1);

      // Si on est très proche, on "mange" le nutriment (on le retire pas pour laisser les autres venir)
      this.life += 2; // Gagne de l'énergie
    }

    // Ajout de bruit naturel (Brownian motion)
    let noiseAngle = map(noise(this.pos.x * 0.01, this.pos.y * 0.01, frameCount * 0.01), 0, 1, -this.wobble, this.wobble);
    this.vel.rotate(noiseAngle);

    this.pos.add(this.vel);

    // Bordures
    if (this.pos.x < 0 || this.pos.x > width || this.pos.y < 0 || this.pos.y > height) {
      this.isDead = true;
    }
  }

  branch() {
    // Crée une nouvelle branche avec un angle légèrement différent
    let angleOffset = random(-PI/3, PI/3);
    let newAngle = this.vel.heading() + angleOffset;
    return new Hypha(this.pos, newAngle);
  }

  display() {
    // La couleur s'éteint avec la vie
    let alpha = map(this.life, 0, 200, 0, 255);
    strokeWeight(map(this.life, 0, 200, 0.5, 2));

    // On utilise la couleur définie
    let c = color(red(this.color), green(this.color), blue(this.color), alpha);
    stroke(c);

    line(this.prevPos.x, this.prevPos.y, this.pos.x, this.pos.y);
  }
}

function drawUI() {
  fill(255);
  noStroke();
  textFont('Courier New');
  textSize(12);
  textAlign(LEFT, TOP);

  text("SILICO_MYCELIUM // V.2.6", 20, 20);
  text("COLONY_SIZE: " + hyphae.length + " HYPHAE", 20, 35);
  text("NUTRIENT_DENSITY: " + nutrients.length, 20, 50);
}

function mousePressed() {
  // Planter une nouvelle colonie
  for(let i=0; i<5; i++){
    hyphae.push(new Hypha(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), random(TWO_PI)));
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(0);
}

